function BOX(worlds, R, S):
  return { w in worlds : forall v ((R(w,v)) -> v in S) }

function STRATIFY(worlds, R, kmax):
  chain <- []
  cur <- empty set
  for t in 0..kmax:
    append cur to chain        // cur = box^t(empty)
    cur <- BOX(worlds, R, cur)
  return chain                  // chain[k] = { w : rank w < k }

